using System.Globalization;
using System.Text;
using Microsoft.VisualBasic.FileIO;
namespace TsScheduler;
// Independent implementation of the data layout verified in TsRename 1.25.
internal static class ChSet3Compatibility
{
 internal sealed record Channel(string Name,int Sid,int Tsid,int Onid,int Type,int Epg=1,int Search=1){internal ulong Key=>((ulong)Onid<<32)|((ulong)Tsid<<16)|(uint)Sid;}
 internal static readonly Encoding ShiftJis=Encoding.GetEncoding(932,EncoderFallback.ExceptionFallback,DecoderFallback.ExceptionFallback);
 internal static List<Channel> ReadCh2(string path){using var reader=new TextFieldParser(path,ShiftJis,true){TextFieldType=FieldType.Delimited,HasFieldsEnclosedInQuotes=true,TrimWhiteSpace=true,CommentTokens=[";"]};reader.SetDelimiters(",");var rows=new List<Channel>();while(!reader.EndOfData){var f=reader.ReadFields();if(f==null)continue;if(f.Length<8||!Number(f[5],out int sid)||!Number(f[7],out int tsid)||!Number(f[6],out int onid)||!Number(f[4],out int type)||sid==0||tsid==0||onid==0)throw new InvalidDataException("チャンネルIDを確認できない行があります："+Path.GetFileName(path));rows.Add(new(f[0],sid,tsid,onid,type));}return rows;}
 static bool Number(string text,out int value)=>int.TryParse(text,NumberStyles.None,CultureInfo.InvariantCulture,out value)&&value is >=0 and <=65535;
 internal static List<Channel> Parse(string text){if(text.StartsWith('\ufeff')||text.Contains('\0'))throw new InvalidDataException("BOMやUTF-16は使用できません。Shift_JISで保存してください。");if(text.Replace("\r\n","").Contains('\n'))throw new InvalidDataException("改行はCRLFにしてください。LFだけでは複数局を読み込めません。");var rows=new List<Channel>();var keys=new HashSet<ulong>();foreach(string line in text.Split("\r\n")){if(line.Length==0)continue;var f=line.Split('\t');if(f.Length!=7||string.IsNullOrWhiteSpace(f[0]))throw new InvalidDataException("7項目のタブ区切りが必要です。見出し行は付けません。");var values=new int[6];for(int i=0;i<6;i++)if(!Number(f[i+1],out values[i]))throw new InvalidDataException("IDやフラグは10進数で指定してください。");if(values[0]==0||values[1]==0||values[2]==0||values[4]>1||values[5]>1)throw new InvalidDataException("SID・TSID・ONIDとフラグを確認してください。");var row=new Channel(f[0],values[0],values[1],values[2],values[3],values[4],values[5]);if(!keys.Add(row.Key))throw new InvalidDataException("SID・TSID・ONIDが同じ行が重複しています。");rows.Add(row);}return rows;}
 internal static byte[] Encode(IEnumerable<Channel> channels){string text=string.Join("\r\n",channels.Select(c=>string.Join("\t",c.Name,c.Sid,c.Tsid,c.Onid,c.Type,c.Epg,c.Search)))+"\r\n";if(Parse(text).Count==0)throw new InvalidDataException("保存する局がありません。");return ShiftJis.GetBytes(text);}
 internal static string Diagnose(string path){byte[] bytes=File.ReadAllBytes(path);try{if(bytes.AsSpan().StartsWith(new byte[]{0xef,0xbb,0xbf}))throw new InvalidDataException("UTF-8のBOMが付いています。Shift_JISで保存してください。");var rows=Parse(ShiftJis.GetString(bytes));return $"TsRename 1.25用の書式：{rows.Count}局を確認。局名・SID・TSID・ONIDを録画データと照合してください。";}catch(Exception e)when(e is InvalidDataException or DecoderFallbackException){return "設定の確認が必要："+e.Message;}}
 internal static void Save(string path,IEnumerable<Channel> channels,string home){byte[] after=Encode(channels);byte[]? before=File.Exists(path)?File.ReadAllBytes(path):null;if(before!=null)TsRenameSupport.Backup(path,home);string temp=path+".zoo-"+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllBytes(temp,after);if(before==null){File.Move(temp,path,false);}else{if(!File.ReadAllBytes(path).SequenceEqual(before))throw new IOException("設定ファイルが更新されました。確認し直してください。");File.Replace(temp,path,null);}}finally{if(File.Exists(temp))File.Delete(temp);}}
}
internal sealed partial class MainForm
{
 void ShowChSet3Generator(IWin32Window owner,string executable){using var files=new OpenFileDialog{Title="TVTestのチャンネル設定を選択",Filter="チャンネル設定（*.ch2）|*.ch2",Multiselect=true,CheckFileExists=true};if(files.ShowDialog(owner)!=DialogResult.OK)return;List<ChSet3Compatibility.Channel> channels;try{channels=files.FileNames.SelectMany(ChSet3Compatibility.ReadCh2).GroupBy(c=>c.Key).Select(g=>g.First()).OrderBy(c=>c.Onid).ThenBy(c=>c.Tsid).ThenBy(c=>c.Sid).ToList();if(channels.Count==0)throw new InvalidDataException("局情報がありません。");}catch(Exception e){MessageBox.Show(owner,e.Message,"局情報を読み込めません");return;}
  using var dialog=new Form{Text="TsRename用の局名を設定",Font=Font,ClientSize=new Size(880,560),MinimumSize=new Size(760,440),StartPosition=FormStartPosition.CenterParent};var grid=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Color.White,ScrollBars=ScrollBars.Vertical};grid.Columns.Add("name","出力する局名");foreach(string title in new[]{"SID","TSID","ONID","種別"}){int index=grid.Columns.Add(title,title);grid.Columns[index].ReadOnly=true;grid.Columns[index].FillWeight=45;}grid.Columns[0].FillWeight=160;foreach(var channel in channels){int index=grid.Rows.Add(channel.Name,channel.Sid,channel.Tsid,channel.Onid,channel.Type);grid.Rows[index].Tag=channel;}ModernScrollBar.Attach(grid);
  var note=new Label{Dock=DockStyle.Top,Height=84,Padding=new Padding(12),Text="局名は編集できます。SID・TSID・ONIDはチャンネル設定から取得します。\nShift_JIS・タブ区切り・CRLFで保存します。TsRename.exeと同じフォルダーへ保存し、TsRenameを再起動してください。"};var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,AutoSize=true,Padding=new Padding(10)};var save=new Button{Text="ChSet3.txtとして保存",AutoSize=true};var cancel=new Button{Text="閉じる",AutoSize=true,DialogResult=DialogResult.Cancel};buttons.Controls.AddRange([save,cancel]);dialog.Controls.Add(grid);dialog.Controls.Add(note);dialog.Controls.Add(buttons);dialog.CancelButton=cancel;
  save.Click+=(_,_)=>{try{grid.EndEdit();var values=grid.Rows.Cast<DataGridViewRow>().Select(row=>((ChSet3Compatibility.Channel)row.Tag!) with{Name=Convert.ToString(row.Cells[0].Value)??""}).ToList();using var output=new SaveFileDialog{Filter="チャンネル対応表（ChSet3.txt）|*.txt",FileName="ChSet3.txt",InitialDirectory=File.Exists(executable)?Path.GetDirectoryName(executable):"",OverwritePrompt=true};if(output.ShowDialog(dialog)!=DialogResult.OK)return;ChSet3Compatibility.Save(output.FileName,values,RecommendationHome);MessageBox.Show(dialog,"保存しました。既存ファイルがあった場合はバックアップ済みです。\nTsRenameを再起動して@CH3を確認してください。");dialog.DialogResult=DialogResult.OK;}catch(Exception e){MessageBox.Show(dialog,e.Message,"保存できません");}};StyleControls(dialog);dialog.ShowDialog(owner);
 }
}
